-- npc_text used for Sir Gideon's "Tell me about this place" gossip page (see lua_scripts/sir_gideon_gossip.lua)
DELETE FROM `npc_text` WHERE `ID` = 200001;
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`) VALUES
(200001,
'Ah. A curious one. Good.\n\nYou are not alone here, if you choose not to be. Companions can be called - bound to follow you, fight beside you, carry your burdens. They answer to commands. They can be geared, directed, dismissed. Some of them can even be your own characters, walking beside you rather than sitting idle at the login screen.\n\nShould this world feel too fast or too slow for you - look down at your experience bar. Right-click it. Alternatively, .xp set followed by a number will do the same. You are in control of your own pace.\n\nOne more thing. Inside the auction house of your capital city, there is a man who deals in appearances. He asks no great deeds of you. He is simply there, waiting.\n\nNow go.',
'Ah. A curious one. Good.\n\nYou are not alone here, if you choose not to be. Companions can be called - bound to follow you, fight beside you, carry your burdens. They answer to commands. They can be geared, directed, dismissed. Some of them can even be your own characters, walking beside you rather than sitting idle at the login screen.\n\nShould this world feel too fast or too slow for you - look down at your experience bar. Right-click it. Alternatively, .xp set followed by a number will do the same. You are in control of your own pace.\n\nOne more thing. Inside the auction house of your capital city, there is a man who deals in appearances. He asks no great deeds of you. He is simply there, waiting.\n\nNow go.',
